        u_xlat2 = (u_xlatb1.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat22;
        u_xlat3 = texture(Mask, acScreenNorm.xy);
        u_xlat4 = (-u_xlat3) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat4;
        u_xlat0 = u_xlat2 * u_xlat3 + u_xlat0;
        u_xlat1 = u_xlat3.x * u_xlat0.w;
        fragColor.w = (u_xlatb1.y) ? u_xlat1 : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat22;
    }
    return;
}
